10	package org.elasticsearch.core;
11	
12	import java.time.Duration;
13	import java.util.Locale;
14	import java.util.Objects;
15	import java.util.concurrent.TimeUnit;
16	
17	public class TimeValue implements Comparable<TimeValue> {
18	
19	    /** How many nano-seconds in one milli-second */
20	    public static final long NSEC_PER_MSEC = TimeUnit.NANOSECONDS.convert(1, TimeUnit.MILLISECONDS);
21	
22	    public static final TimeValue MINUS_ONE = new TimeValue(-1, TimeUnit.MILLISECONDS);
23	    public static final TimeValue ZERO = new TimeValue(0, TimeUnit.MILLISECONDS);
24	    public static final TimeValue MAX_VALUE = new TimeValue(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
25	    public static final TimeValue THIRTY_SECONDS = new TimeValue(30, TimeUnit.SECONDS);
26	    public static final TimeValue ONE_MINUTE = new TimeValue(1, TimeUnit.MINUTES);
27	    public static final TimeValue ONE_HOUR = new TimeValue(1, TimeUnit.HOURS);
28	
29	    private static final long C0 = 1L;
30	    private static final long C1 = C0 * 1000L;
31	    private static final long C2 = C1 * 1000L;
32	    private static final long C3 = C2 * 1000L;
33	    private static final long C4 = C3 * 60L;
34	    private static final long C5 = C4 * 60L;
35	    private static final long C6 = C5 * 24L;
36	
37	    private final long duration;
38	    private final TimeUnit timeUnit;
39	
40	    public TimeValue(long millis) {
41	        this(millis, TimeUnit.MILLISECONDS);
42	    }
43	
44	    public TimeValue(long duration, TimeUnit timeUnit) {
45	        if (duration < -1) {
46	            throw new IllegalArgumentException("duration cannot be negative, was given [" + duration + "]");
47	        }
48	        this.duration = duration;
49	        this.timeUnit = timeUnit;
50	    }
51	
52	    public static TimeValue timeValueNanos(long nanos) {
53	        return new TimeValue(nanos, TimeUnit.NANOSECONDS);
54	    }
55	
56	    public static TimeValue timeValueMillis(long millis) {
57	        if (millis == 0) {
58	            return ZERO;
59	        }
60	        if (millis == -1) {
61	            return MINUS_ONE;
62	        }
63	        return new TimeValue(millis, TimeUnit.MILLISECONDS);
64	    }
65	
66	    public static TimeValue timeValueSeconds(long seconds) {
67	        if (seconds == 30) {
68	            // common value, no need to allocate each time
69	            return THIRTY_SECONDS;
70	        }
71	        return new TimeValue(seconds, TimeUnit.SECONDS);
72	    }
73	
74	    public static TimeValue timeValueMinutes(long minutes) {
75	        if (minutes == 1) {
76	            // common value, no need to allocate each time
77	            return ONE_MINUTE;
78	        }
79	        return new TimeValue(minutes, TimeUnit.MINUTES);
80	    }
81	
82	    public static TimeValue timeValueHours(long hours) {
83	        return new TimeValue(hours, TimeUnit.HOURS);
84	    }
85	
86	    public static TimeValue timeValueDays(long days) {
87	        // 106751.9 days is Long.MAX_VALUE nanoseconds, so we cannot store 106752 days
88	        if (days > 106751) {
89	            throw new IllegalArgumentException("time value cannot store values greater than 106751 days");
90	        }
91	        return new TimeValue(days, TimeUnit.DAYS);
92	    }
93	
94	    /**
95	     * @return the {@link TimeValue} object that has the least duration.
96	     */
97	    public static TimeValue min(TimeValue time1, TimeValue time2) {
98	        return time1.compareTo(time2) < 0 ? time1 : time2;
99	    }
100	
101	    /**
102	     * @return the unit used for the this time value, see {@link #duration()}
103	     */
104	    public TimeUnit timeUnit() {
105	        return timeUnit;
106	    }
107	
108	    /**
109	     * @return the number of {@link #timeUnit()} units this value contains
110	     */
111	    public long duration() {
112	        return duration;
113	    }
114	
115	    public long nanos() {
116	        return timeUnit.toNanos(duration);
117	    }
118	
119	    public long getNanos() {
120	        return nanos();
121	    }
122	
123	    public long micros() {
124	        return timeUnit.toMicros(duration);
125	    }
126	
127	    public long getMicros() {
128	        return micros();
129	    }
130	
131	    public long millis() {
132	        return timeUnit.toMillis(duration);
133	    }
134	
135	    public long getMillis() {
136	        return millis();
137	    }
138	
139	    public long seconds() {
140	        return timeUnit.toSeconds(duration);
141	    }
142	
143	    public long getSeconds() {
144	        return seconds();
145	    }
146	
147	    public long minutes() {
148	        return timeUnit.toMinutes(duration);
149	    }
150	
151	    public long getMinutes() {
152	        return minutes();
153	    }
154	
155	    public long hours() {
156	        return timeUnit.toHours(duration);
157	    }
158	
159	    public long getHours() {
160	        return hours();
161	    }
162	
163	    public long days() {
164	        return timeUnit.toDays(duration);
165	    }
166	
167	    public long getDays() {
168	        return days();
169	    }
170	
171	    public double microsFrac() {
172	        return ((double) nanos()) / C1;
173	    }
174	
175	    public double getMicrosFrac() {
176	        return microsFrac();
177	    }
178	
179	    public double millisFrac() {
180	        return ((double) nanos()) / C2;
181	    }
182	
183	    public double getMillisFrac() {
184	        return millisFrac();
185	    }
186	
187	    public double secondsFrac() {
188	        return ((double) nanos()) / C3;
189	    }
190	
191	    public double getSecondsFrac() {
192	        return secondsFrac();
193	    }
194	
195	    public double minutesFrac() {
196	        return ((double) nanos()) / C4;
197	    }
198	
199	    public double getMinutesFrac() {
200	        return minutesFrac();
201	    }
202	
203	    public double hoursFrac() {
204	        return ((double) nanos()) / C5;
205	    }
206	
207	    public double getHoursFrac() {
208	        return hoursFrac();
209	    }
210	
211	    public double daysFrac() {
212	        return ((double) nanos()) / C6;
213	    }
214	
215	    public double getDaysFrac() {
216	        return daysFrac();
217	    }
218	
219	    /**
220	     * Returns a {@link String} representation of the current {@link TimeValue}.
221	     *
222	     * Note that this method might produce fractional time values (ex 1.6m) which cannot be
223	     * parsed by method like {@link TimeValue#parse(String, String, String, String)}.
224	     *
225	     * Also note that the maximum string value that will be generated is
226	     * {@code 106751.9d} due to the way that values are internally converted
227	     * to nanoseconds (106751.9 days is Long.MAX_VALUE nanoseconds)
228	     */
229	    @Override
230	    public String toString() {
231	        return this.toHumanReadableString(1);
232	    }
233	
234	    /**
235	     * Returns a {@link String} representation of the current {@link TimeValue}.
236	     *
237	     * Note that this method might produce fractional time values (ex 1.6m) which cannot be
238	     * parsed by method like {@link TimeValue#parse(String, String, String, String)}. The number of
239	     * fractional decimals (up to 10 maximum) are truncated to the number of fraction pieces
240	     * specified.
241	     *
242	     * Also note that the maximum string value that will be generated is
243	     * {@code 106751.9d} due to the way that values are internally converted
244	     * to nanoseconds (106751.9 days is Long.MAX_VALUE nanoseconds)
245	     *
246	     * @param fractionPieces the number of decimal places to include
247	     */
248	    public String toHumanReadableString(int fractionPieces) {
249	        if (duration < 0) {
250	            return Long.toString(duration);
251	        }
252	        long nanos = nanos();
253	        if (nanos == 0) {
254	            return "0s";
255	        }
256	        double value = nanos;
257	        String suffix = "nanos";
258	        if (nanos >= C6) {
259	            value = daysFrac();
260	            suffix = "d";
261	        } else if (nanos >= C5) {
262	            value = hoursFrac();
263	            suffix = "h";
264	        } else if (nanos >= C4) {
265	            value = minutesFrac();
266	            suffix = "m";
267	        } else if (nanos >= C3) {
268	            value = secondsFrac();
269	            suffix = "s";
270	        } else if (nanos >= C2) {
271	            value = millisFrac();
272	            suffix = "ms";
273	        } else if (nanos >= C1) {
274	            value = microsFrac();
275	            suffix = "micros";
276	        }
277	        // Limit fraction pieces to a min of 0 and maximum of 10
278	        return formatDecimal(value, Math.min(10, Math.max(0, fractionPieces))) + suffix;
279	    }
280	
281	    private static String formatDecimal(double value, int fractionPieces) {
282	        String p = String.valueOf(value);
283	        int totalLength = p.length();
284	        int ix = p.indexOf('.') + 1;
285	        int ex = p.indexOf('E');
286	        // Location where the fractional values end
287	        int fractionEnd = ex == -1 ? Math.min(ix + fractionPieces, totalLength) : ex;
288	
289	        // Determine the value of the fraction, so if it were .000 the
290	        // actual long value is 0, in which case, it can be elided.
291	        long fractionValue;
292	        try {
293	            fractionValue = Long.parseLong(p.substring(ix, fractionEnd));
294	        } catch (NumberFormatException e) {
295	            fractionValue = 0;
296	        }
297	
298	        if (fractionValue == 0 || fractionPieces <= 0) {
299	            // Either the part of the fraction we were asked to report is
300	            // zero, or the user requested 0 fraction pieces, so return
301	            // only the integral value
302	            if (ex != -1) {
303	                return p.substring(0, ix - 1) + p.substring(ex);
304	            } else {
305	                return p.substring(0, ix - 1);
306	            }
307	        } else {
308	            // Build up an array of fraction characters, without going past
309	            // the end of the string. This keeps track of trailing '0' chars
310	            // that should be truncated from the end to avoid getting a
311	            // string like "1.3000d" (returning "1.3d" instead) when the
312	            // value is 1.30000009
313	            char[] fractions = new char[fractionPieces];
314	            int fracCount = 0;
315	            int truncateCount = 0;
316	            for (int i = 0; i < fractionPieces; i++) {
317	                int position = ix + i;
318	                if (position >= fractionEnd) {
319	                    // No more pieces, the fraction has ended
320	                    break;
321	                }
322	                char fraction = p.charAt(position);
323	                if (fraction == '0') {
324	                    truncateCount++;
325	                } else {
326	                    truncateCount = 0;
327	                }
328	                fractions[i] = fraction;
329	                fracCount++;
330	            }
331	
332	            // Generate the fraction string from the char array, truncating any trailing zeros
333	            String fractionStr = new String(fractions, 0, fracCount - truncateCount);
334	
335	            if (ex != -1) {
336	                return p.substring(0, ix) + fractionStr + p.substring(ex);
337	            } else {
338	                return p.substring(0, ix) + fractionStr;
339	            }
340	        }
341	    }
342	
343	    public String getStringRep() {
344	        if (duration < 0 && TimeUnit.MILLISECONDS == timeUnit) {
345	            return Long.toString(duration);
346	        }
347	        return switch (timeUnit) {
348	            case NANOSECONDS -> duration + "nanos";
349	            case MICROSECONDS -> duration + "micros";
350	            case MILLISECONDS -> duration + "ms";
351	            case SECONDS -> duration + "s";
352	            case MINUTES -> duration + "m";
353	            case HOURS -> duration + "h";
354	            case DAYS -> duration + "d";
355	        };
356	    }
357	
358	    /**
359	     * @param sValue       Value to parse, which may not be {@code null}.
360	     * @param settingName  Name of the parameter or setting. On invalid input, this value is included in the exception message. Otherwise,
361	     *                     this parameter is unused.
362	     * @return The {@link TimeValue} which the input string represents.
363	     */
364	    public static TimeValue parseTimeValue(String sValue, String settingName) {
365	        Objects.requireNonNull(settingName);
366	        Objects.requireNonNull(sValue);
367	        return parseTimeValue(sValue, null, settingName);
368	    }
369	
370	    /**
371	     * @param sValue       Value to parse, which may be {@code null}.
372	     * @param defaultValue Value to return if {@code sValue} is {@code null}.
373	     * @param settingName  Name of the parameter or setting. On invalid input, this value is included in the exception message. Otherwise,
374	     *                     this parameter is unused.
375	     * @return The {@link TimeValue} which the input string represents, or {@code defaultValue} if the input is {@code null}.
376	     */
377	    public static TimeValue parseTimeValue(@Nullable String sValue, TimeValue defaultValue, String settingName) {
378	        settingName = Objects.requireNonNull(settingName);
379	        if (sValue == null) {
380	            return defaultValue;
381	        }
382	        final String normalized = sValue.toLowerCase(Locale.ROOT).trim();
383	        if (normalized.endsWith("nanos")) {
384	            return TimeValue.timeValueNanos(parse(sValue, normalized, "nanos", settingName));
385	        } else if (normalized.endsWith("micros")) {
386	            return new TimeValue(parse(sValue, normalized, "micros", settingName), TimeUnit.MICROSECONDS);
387	        } else if (normalized.endsWith("ms")) {
388	            return TimeValue.timeValueMillis(parse(sValue, normalized, "ms", settingName));
389	        } else if (normalized.endsWith("s")) {
390	            return TimeValue.timeValueSeconds(parse(sValue, normalized, "s", settingName));
391	        } else if (sValue.endsWith("m")) {
392	            // parsing minutes should be case-sensitive as 'M' means "months", not "minutes"; this is the only special case.
393	            return TimeValue.timeValueMinutes(parse(sValue, normalized, "m", settingName));
394	        } else if (normalized.endsWith("h")) {
395	            return TimeValue.timeValueHours(parse(sValue, normalized, "h", settingName));
396	        } else if (normalized.endsWith("d")) {
397	            return new TimeValue(parse(sValue, normalized, "d", settingName), TimeUnit.DAYS);
398	        } else if (normalized.matches("-0*1")) {
399	            return TimeValue.MINUS_ONE;
400	        } else if (normalized.matches("0+")) {
401	            return TimeValue.ZERO;
402	        } else {
403	            // Missing units:
404	            throw new IllegalArgumentException(
405	                "failed to parse setting [" + settingName + "] with value [" + sValue + "] as a time value: unit is missing or unrecognized"
406	            );
407	        }
408	    }
409	
410	    private static long parse(final String initialInput, final String normalized, final String suffix, String settingName) {
411	        final String s = normalized.substring(0, normalized.length() - suffix.length()).trim();
412	        try {
413	            final long value = Long.parseLong(s);
414	            if (value < -1) {
415	                // -1 is magic, but reject any other negative values
416	                throw new IllegalArgumentException(
417	                    "failed to parse setting ["
418	                        + settingName
419	                        + "] with value ["
420	                        + initialInput
421	                        + "] as a time value: negative durations are not supported"
422	                );
423	            }
424	            return value;
425	        } catch (final NumberFormatException e) {
426	            try {
427	                @SuppressWarnings("unused")
428	                final double ignored = Double.parseDouble(s);
429	                throw new IllegalArgumentException("failed to parse [" + initialInput + "], fractional time values are not supported", e);
430	            } catch (final NumberFormatException ignored) {
431	                throw new IllegalArgumentException("failed to parse [" + initialInput + "]", e);
432	            }
433	        }
434	    }
435	
436	    @Override
437	    public boolean equals(Object o) {
438	        if (this == o) return true;
439	        if (o == null || getClass() != o.getClass()) return false;
440	
441	        return this.compareTo(((TimeValue) o)) == 0;
442	    }
443	
444	    @Override
445	    public int hashCode() {
446	        return Double.hashCode(((double) duration) * timeUnit.toNanos(1));
447	    }
448	
449	    public static long nsecToMSec(long ns) {
450	        return ns / NSEC_PER_MSEC;
451	    }
452	
453	    @Override
454	    public int compareTo(TimeValue timeValue) {
455	        double thisValue = ((double) duration) * timeUnit.toNanos(1);
456	        double otherValue = ((double) timeValue.duration) * timeValue.timeUnit.toNanos(1);
457	        return Double.compare(thisValue, otherValue);
458	    }
459	
460	    public Duration toDuration() {
461	        return Duration.ofNanos(nanos());
462	    }
463	}
